    ('1e15edfc-150b-5c24-aa0a-7aeaf5f19961'::uuid, 'buildwithjess', 'Jess Ferrara', 'buildwithjess@agentdistrict.demo'),
    ('471d82e7-4a36-5eee-a610-f87876298911'::uuid, 'agentmax', 'Max Ortega', 'agentmax@agentdistrict.demo'),
