    ('10387730-d7cb-59d5-92f4-8b2b3b9169ee'::uuid, 'devdan', 'Dan Whitaker', 'devdan@agentdistrict.demo'),
    ('124ec57f-29a7-5b0e-ad9d-0d26f54cd038'::uuid, 'maria-work', 'Maria Delgado', 'maria-work@agentdistrict.demo'),
    ('ae8a6c08-5c88-55e9-86ed-d067446aa35a'::uuid, 'scale-j', 'Jordan Pike', 'scale-j@agentdistrict.demo'),
    ('622241e5-0c44-5585-bd30-a2a447b530f7'::uuid, 'roofco-ray', 'Ray Castellano', 'roofco-ray@agentdistrict.demo'),
    ('70968bbd-97ab-590c-8910-ebc951ba141c'::uuid, 'tampa-tess', 'Tess Nakamura', 'tampa-tess@agentdistrict.demo'),
    ('a8f1f350-932a-5420-97ca-c175ba8549bd'::uuid, 'orlando-omar', 'Omar Haddad', 'orlando-omar@agentdistrict.demo'),
    ('f45605f2-4e32-5824-92f7-ca5dfe2d79e4'::uuid, 'coastal-carla', 'Carla Mendes', 'coastal-carla@agentdistrict.demo'),
    ('b9945c39-a4f7-554f-8885-41b9775afd12'::uuid, 'nina-ops', 'Nina Alvarez', 'nina-ops@agentdistrict.demo')
    ) as t(id, handle, display_name, email)
  loop
    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password,
      email_confirmed_at, created_at, updated_at,
      raw_app_meta_data, raw_user_meta_data, is_super_admin,
      confirmation_token, email_change, email_change_token_new, recovery_token
    )
    values (
      '00000000-0000-0000-0000-000000000000',
      demo.id,
      'authenticated',
      'authenticated',
      demo.email,
      '',
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      jsonb_build_object('handle', demo.handle, 'display_name', demo.display_name),
      false,
      '', '', '', ''
    )
    on conflict (id) do nothing;
  end loop;
end
$$;

