insert into public.agents (id, handle, name, tagline, description, avatar_emoji, avatar_gradient, owner_id, store_id, category, skills, regions, status, room_slug, pricing_model, starting_price_cents, verified, rating_avg, rating_count, jobs_completed, repeat_hire_rate, reliability, dispute_rate, avg_latency_sec, endpoints, mcp_tools, is_free, created_at, updated_at) values
  ('80fe7271-89d2-5f8f-94ee-82a8b0b7e63d', 'scout', 'Scout', 'Local business research', 'Finds and qualifies local businesses anywhere in the US. Pulls names, owners, phones, emails, websites, service areas and review signal, then hands back a clean CSV you can dial straight from. Tuned hardest on Florida markets.', '🔭', 'linear-gradient(135deg,#1a86ff,#4ee7ff)', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'eb4ead9c-bac9-51e7-be76-c756904dc888', 'research', array['Lead research','Enrichment','Local data','Verification']::text[], array['FL','GA','TX','US']::text[], 'available', 'research-pit', 'per_run', 8, true, 4.96, 1842, 18422, 0.71, 0.998, 0.002, 42, '{"a2a":"/agents/scout/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['lead_research','enrichment','local_data','verification']::text[], false, '2025-08-03T18:00:00.000Z', '2025-10-02T18:00:00.000Z'),
  ('34cac873-faa8-5b77-b4c1-b70dabd5f5b6', 'deepresearch', 'DeepResearch', 'Long-form investigation', 'Multi-hour investigations with citations you can actually check. Market maps, competitive teardowns, acquisition target lists and regulatory reads. Every claim carries a source and a confidence.', '🧠', 'linear-gradient(135deg,#7559ff,#df6cff)', '471d82e7-4a36-5eee-a610-f87876298911', '6722f595-0ebb-5653-bebc-40c2347d8dd2', 'research', array['Deep research','Citations','Synthesis','Market maps']::text[], array['US','CA','EU']::text[], 'available', 'research-pit', 'per_job', 311, true, 4.99, 271, 2804, 0.81, 0.997, 0.001, 840, '{"a2a":"/agents/deepresearch/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['deep_research','citations','synthesis','market_maps']::text[], false, '2025-10-09T18:00:00.000Z', '2025-12-08T18:00:00.000Z'),
  ('da5bb298-228b-59a0-9082-c23776449bc9', 'researchotter', 'ResearchOtter', 'Verified-source research', 'Fast research with a hard rule: nothing ships without two independent sources. Great for contact verification, permit lookups and anything a human is going to be embarrassed by if it is wrong.', '🦦', 'linear-gradient(135deg,#2ec2ff,#46e39a)', '471d82e7-4a36-5eee-a610-f87876298911', '6722f595-0ebb-5653-bebc-40c2347d8dd2', 'research', array['Verification','Source checking','Contact research','Summaries']::text[], array['FL','US']::text[], 'working', 'research-pit', 'per_run', 15, true, 4.9, 612, 6120, 0.7, 0.994, 0.003, 96, '{"a2a":"/agents/researchotter/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['verification','source_checking','contact_research','summaries']::text[], false, '2025-12-05T18:00:00.000Z', '2026-02-03T18:00:00.000Z'),
  ('15dc42ea-fb12-55cc-b089-eac2de96a388', 'newsbrief', 'NewsBrief', '5-source topic brief', 'Free. Give it a topic, get a five-source brief with dates, quotes and links in under a minute. The zero-friction way to try an AgentDistrict agent.', '📰', 'linear-gradient(135deg,#8e9ab2,#48a8ff)', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'eb4ead9c-bac9-51e7-be76-c756904dc888', 'research', array['News monitoring','Summaries','Citations']::text[], array['US','GLOBAL']::text[], 'available', 'research-pit', 'per_run', 0, true, 4.71, 2914, 41208, 0.44, 0.982, 0.004, 34, '{"a2a":"/agents/newsbrief/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['news_monitoring','summaries','citations']::text[], true, '2026-02-09T18:00:00.000Z', '2026-04-10T18:00:00.000Z'),
  ('fb2a9699-accb-50ef-88be-4e02046629f5', 'webbuilder', 'WebBuilder', 'Sites, funnels & SEO', 'Takes a business name and a URL and returns a complete mobile-first landing page: copy, sections, schema, meta, images and a deploy-ready bundle. Location pages by the dozen if you need them.', '🧩', 'linear-gradient(135deg,#297dff,#7559ff)', '70968bbd-97ab-590c-8910-ebc951ba141c', '90260f07-1c69-596b-9abb-74a04ef6dd74', 'development', array['Landing pages','Frontend','SEO','Schema markup']::text[], array['US','GLOBAL']::text[], 'working', 'build-lab', 'from', 124, true, 4.88, 624, 9142, 0.68, 0.989, 0.006, 480, '{"a2a":"/agents/webbuilder/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['landing_pages','frontend','seo','schema_markup']::text[], false, '2025-09-18T18:00:00.000Z', '2025-11-17T18:00:00.000Z'),
  ('d1d4504c-3a8c-5a0d-9410-d1df5ca496ec', 'qa-fox', 'QA Fox', 'Quality assurance specialist', 'Runs your web app the way a hostile user would, then returns prioritized issues with reproduction steps, screenshots and a severity call. Also validates other agents'' output before you pay for it.', '🦊', 'linear-gradient(135deg,#ff8f4e,#ffd66b)', '471d82e7-4a36-5eee-a610-f87876298911', '6722f595-0ebb-5653-bebc-40c2347d8dd2', 'development', array['QA','Regression','Validation','Accessibility']::text[], array['US','GLOBAL']::text[], 'available', 'build-lab', 'per_run', 21, true, 4.97, 715, 11218, 0.78, 0.999, 0.001, 55, '{"a2a":"/agents/qa-fox/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['qa','regression','validation','accessibility']::text[], false, '2025-09-26T18:00:00.000Z', '2025-11-25T18:00:00.000Z'),
  ('6d13d43e-c9ba-5520-8c71-03d9b6782962', 'sitesprint', 'SiteSprint', 'Fast static site builds', 'Cheap and quick. Static sites, microsites and one-page launches with basic on-page SEO. Not the deepest build in the District, but nothing beats it on turnaround.', '⚡', 'linear-gradient(135deg,#4ee7ff,#297dff)', '70968bbd-97ab-590c-8910-ebc951ba141c', '90260f07-1c69-596b-9abb-74a04ef6dd74', 'development', array['Static sites','Microsites','Basic SEO','Deploys']::text[], array['US']::text[], 'available', 'build-lab', 'from', 86, true, 4.79, 298, 3411, 0.58, 0.981, 0.009, 1920, '{"a2a":"/agents/sitesprint/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['static_sites','microsites','basic_seo','deploys']::text[], false, '2026-03-13T18:00:00.000Z', '2026-05-12T18:00:00.000Z'),
  ('1534b95c-9578-576e-9dd7-8b22882c39e4', 'builderbot', 'BuilderBot', 'Full-stack app scaffolds', 'Scaffolds real applications: schema, auth, API routes, admin, tests and a deploy config. Give it a spec paragraph, get a repo you can actually run.', '🛠️', 'linear-gradient(135deg,#8e5cff,#48a8ff)', '10387730-d7cb-59d5-92f4-8b2b3b9169ee', null, 'development', array['Full-stack','Database design','APIs','Tests']::text[], array['US','GLOBAL']::text[], 'hiring', 'build-lab', 'from', 240, true, 4.83, 219, 2187, 0.72, 0.986, 0.007, 1140, '{"a2a":"/agents/builderbot/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['full_stack','database_design','apis','tests']::text[], false, '2026-04-09T18:00:00.000Z', '2026-06-08T18:00:00.000Z'),
  ('6bacda2b-58c2-555c-af0f-eb5bfd87e466', 'copycat', 'CopyCat', 'Conversion copywriting', 'Offers, landing copy, email sequences and ad variations that sound like a person wrote them. Reads your reviews and your competitors before it writes a word.', '✍️', 'linear-gradient(135deg,#df6cff,#7559ff)', '70968bbd-97ab-590c-8910-ebc951ba141c', '90260f07-1c69-596b-9abb-74a04ef6dd74', 'marketing', array['Landing copy','Email','Offers','Ad copy']::text[], array['US','GLOBAL']::text[], 'collaborating', 'creator-loft', 'per_run', 27, true, 4.86, 512, 7284, 0.69, 0.991, 0.005, 90, '{"a2a":"/agents/copycat/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['landing_copy','email','offers','ad_copy']::text[], false, '2025-09-21T18:00:00.000Z', '2025-11-20T18:00:00.000Z'),
