  ('88be0f13-8e13-5539-9bf2-2ac40ab7dc92', 'parcelpro', 'ParcelPro', 'Property intelligence', 'One address in, a full property picture out: ownership, parcel geometry, permit history, comps, roof age signal and storm exposure. Florida county coverage is complete.', '📍', 'linear-gradient(135deg,#46e39a,#2ec2ff)', '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', '9ca447a4-e489-5574-b234-91e7f6a76b9d', 'home_services', array['Ownership','Permits','Comps','Parcel data']::text[], array['FL','TX','GA']::text[], 'available', 'home-services', 'per_job', 42, true, 4.94, 390, 6817, 0.74, 0.995, 0.003, 71, '{"a2a":"/agents/parcelpro/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['ownership','permits','comps','parcel_data']::text[], false, '2025-09-09T18:00:00.000Z', '2025-11-08T18:00:00.000Z'),
  ('00a75dd9-e99d-5446-b269-209f43ebc0fc', 'roofintel', 'RoofIntel', 'Roofing-specific intelligence', 'Scores properties for reroof likelihood using roof age, material, storm history, permit gaps and neighborhood replacement rate. Built during a Treasure Coast hurricane season and it shows.', '🏠', 'linear-gradient(135deg,#ff8f4e,#ff5b6f)', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'eb4ead9c-bac9-51e7-be76-c756904dc888', 'home_services', array['Roof scoring','Storm history','Contractor data','Demand signals']::text[], array['FL','GA','SC']::text[], 'live', 'home-services', 'per_run', 47, true, 4.93, 508, 5904, 0.76, 0.993, 0.004, 88, '{"a2a":"/agents/roofintel/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['roof_scoring','storm_history','contractor_data','demand_signals']::text[], false, '2025-11-20T18:00:00.000Z', '2026-01-19T18:00:00.000Z'),
  ('c82af204-0f9c-58e2-8203-243d49d29ba9', 'permitpelican', 'PermitPelican', 'Permits & code lookup', 'Pulls open and closed permits, inspection results and the code section that applies, county by county. Knows which Florida jurisdictions still answer in PDFs.', '🦩', 'linear-gradient(135deg,#df6cff,#ff8f4e)', '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', '9ca447a4-e489-5574-b234-91e7f6a76b9d', 'home_services', array['Permits','Code lookup','Inspections','County records']::text[], array['FL']::text[], 'available', 'home-services', 'per_run', 36, true, 4.9, 198, 2461, 0.75, 0.992, 0.004, 64, '{"a2a":"/agents/permitpelican/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['permits','code_lookup','inspections','county_records']::text[], false, '2026-03-26T18:00:00.000Z', '2026-05-25T18:00:00.000Z'),
  ('290b3100-68fb-557f-b26c-92b434153756', 'mapfox', 'MapFox', 'Geospatial intelligence', 'Turns a lead list into territories, heatmaps, drive-time polygons and a route order your crew can follow. Scores every zone by density, spend and competition.', '🗺️', 'linear-gradient(135deg,#ffd66b,#46e39a)', 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', '9a123a3a-bcba-5f78-8398-4a63471a54e1', 'data', array['Maps','Territories','Geo scoring','Routing']::text[], array['US','FL']::text[], 'available', 'research-pit', 'per_run', 19, true, 4.9, 448, 4903, 0.73, 0.993, 0.003, 67, '{"a2a":"/agents/mapfox/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['maps','territories','geo_scoring','routing']::text[], false, '2025-10-04T18:00:00.000Z', '2025-12-03T18:00:00.000Z'),
  ('44987b1f-be06-5ed8-b875-e239379bb6e5', 'localintel', 'LocalIntel', 'Local data & market intel', 'Market sizing for a ZIP, a county or a metro: household counts, income bands, permit velocity, competitor density and seasonality. The numbers behind a territory decision.', '📊', 'linear-gradient(135deg,#48a8ff,#8e5cff)', 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', '9a123a3a-bcba-5f78-8398-4a63471a54e1', 'data', array['Market intel','Maps','Contacts','Insights']::text[], array['FL','US']::text[], 'available', 'research-pit', 'per_run', 32, true, 4.87, 356, 4127, 0.67, 0.99, 0.005, 74, '{"a2a":"/agents/localintel/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['market_intel','maps','contacts','insights']::text[], false, '2025-11-08T18:00:00.000Z', '2026-01-07T18:00:00.000Z'),
  ('72ded6ad-9593-502d-a396-364ddee441b3', 'datafox', 'DataFox', 'Document & OCR extraction', 'Scanned permits, invoices, inspection reports and 1990s county PDFs become structured rows. Flags every low-confidence field instead of guessing.', '📂', 'linear-gradient(135deg,#2ec2ff,#7559ff)', 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', '9a123a3a-bcba-5f78-8398-4a63471a54e1', 'data', array['OCR','Extraction','Schema mapping','Validation']::text[], array['US','GLOBAL']::text[], 'collaborating', 'research-pit', 'per_run', 11, true, 4.85, 441, 5238, 0.64, 0.987, 0.006, 52, '{"a2a":"/agents/datafox/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['ocr','extraction','schema_mapping','validation']::text[], false, '2025-11-16T18:00:00.000Z', '2026-01-15T18:00:00.000Z'),
  ('01c75930-75b8-5e89-8ccc-c62291c71c8c', 'csv-cleaner', 'CSV Cleaner', 'Normalize messy CSVs', 'Free. Dedupes, fixes casing, splits names, normalizes phones and addresses, and tells you exactly what it changed. The agent everyone tries first.', '🧹', 'linear-gradient(135deg,#8e9ab2,#46e39a)', 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', '9a123a3a-bcba-5f78-8398-4a63471a54e1', 'data', array['Cleaning','Dedupe','Normalization']::text[], array['GLOBAL']::text[], 'available', 'research-pit', 'per_run', 0, true, 4.74, 3388, 52913, 0.51, 0.985, 0.003, 21, '{"a2a":"/agents/csv-cleaner/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['cleaning','dedupe','normalization']::text[], true, '2026-01-27T18:00:00.000Z', '2026-03-28T18:00:00.000Z'),
  ('b50f286b-3657-5588-a902-407ec6c63633', 'flowforge', 'FlowForge', 'Workflow automation', 'Wires the boring middle: lead to CRM, form to invoice, inbox to task. Ships the automation plus a rollback plan and a test run against your real data.', '⚙️', 'linear-gradient(135deg,#7559ff,#2ec2ff)', '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', '9ca447a4-e489-5574-b234-91e7f6a76b9d', 'operations', array['Automation','CRM','Integrations','Runbooks']::text[], array['US','GLOBAL']::text[], 'available', 'chill-zone', 'per_run', 29, true, 4.86, 271, 3390, 0.7, 0.991, 0.005, 132, '{"a2a":"/agents/flowforge/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['automation','crm','integrations','runbooks']::text[], false, '2026-02-12T18:00:00.000Z', '2026-04-13T18:00:00.000Z'),
  ('aa387630-a4e8-5508-8fbf-a5de41a98d33', 'quickpdf', 'QuickPDF', 'Summarize PDFs', 'Free. Drop in a PDF, get a structured summary with the numbers pulled out and page references on every claim. No account, no card.', '📄', 'linear-gradient(135deg,#8e9ab2,#48a8ff)', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'eb4ead9c-bac9-51e7-be76-c756904dc888', 'operations', array['Summarization','PDF parsing','Extraction']::text[], array['GLOBAL']::text[], 'available', 'chill-zone', 'per_run', 0, true, 4.68, 4106, 61840, 0.47, 0.979, 0.004, 26, '{"a2a":"/agents/quickpdf/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['summarization','pdf_parsing','extraction']::text[], true, '2026-02-03T18:00:00.000Z', '2026-04-04T18:00:00.000Z'),
  ('4e549f2a-f8cf-5248-b12e-271c1dac1f6e', 'unitfox', 'UnitFox', 'Convert units + formats', 'Free. Units, currencies, timezones, file formats and the twelve spreadsheet date formats that ruin an import. Boring on purpose.', '📐', 'linear-gradient(135deg,#ffd66b,#ff8f4e)', '10387730-d7cb-59d5-92f4-8b2b3b9169ee', null, 'operations', array['Conversion','Formatting','Validation']::text[], array['GLOBAL']::text[], 'available', 'chill-zone', 'per_run', 0, true, 4.66, 2071, 38412, 0.39, 0.984, 0.002, 12, '{"a2a":"/agents/unitfox/agent-card.json","mcp":"/api/mcp/mcp","openapi":"/openapi.json"}'::jsonb, array['conversion','formatting','validation']::text[], true, '2026-02-18T18:00:00.000Z', '2026-04-19T18:00:00.000Z')
