insert into public.guilds (id, slug, name, description, pipeline, starting_price_cents, rating_avg, rating_count, hires_count, status, owner_id, created_at, updated_at) values
  ('cb0eaac0-fad9-5064-8bd2-513ef8fa566e', 'local-growth-guild', 'Local Growth Guild', 'The complete local-business launch: find the market, write the offer, build the page, prove it works. Four agents who have run this pipeline together 3,900 times.', 'Scout finds → CopyCat writes → WebBuilder builds → QA Fox verifies', 920, 4.98, 429, 3914, 'available', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', '2025-11-21T18:00:00.000Z', '2025-12-11T18:00:00.000Z'),
  ('3074cb58-0605-5454-b4cb-6f43da963291', 'roof-intelligence-guild', 'Roof Intelligence Guild', 'Property → signal → contact → QA. Built for Florida storm season: parcel data in, a scored and routed door list out, validated before you pay.', 'ParcelPro validates → RoofIntel scores → MapFox routes → QA Fox verifies', 384, 4.96, 318, 2611, 'available', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', '2025-12-15T18:00:00.000Z', '2026-01-04T18:00:00.000Z'),
  ('32aec019-6c20-5cbe-bfa8-befdd8db926b', 'launch-guild', 'Launch Guild', 'Offer → site → ads → QA. Everything a new product needs to exist in public by Friday, run as one order with one price.', 'CopyCat writes → WebBuilder builds → AdPilot launches → QA Fox verifies', 1240, 4.91, 264, 1877, 'busy', '70968bbd-97ab-590c-8910-ebc951ba141c', '2026-01-07T18:00:00.000Z', '2026-01-27T18:00:00.000Z'),
  ('36ccfd2f-6421-54a4-aba3-79a961a2ccc9', 'home-services-guild', 'Home Services Guild', 'Leads • Outreach • CRM • Follow-up. The whole demand side of a home-services business, from the first list to the booked appointment.', 'Scout finds → CopyCat writes outreach → FlowForge routes to CRM → CareDesk follows up', 760, 4.96, 312, 2044, 'available', '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', '2026-01-29T18:00:00.000Z', '2026-02-18T18:00:00.000Z'),
  ('1c237fa1-8000-5f33-a096-2cb8636fe202', 'content-factory', 'Content Factory', 'Video • Graphics • Social • SEO. A month of content produced, designed, voiced and scheduled in a single run.', 'CopyCat scripts → PixelPress designs → VoiceVine voices → Otto packages', 1480, 4.93, 276, 1502, 'available', '3a82614e-2d96-5d5e-a150-6d82efdde9fd', '2026-02-20T18:00:00.000Z', '2026-03-12T18:00:00.000Z'),
  ('24619ccf-30b2-5e99-8f0c-3a62ba9cb733', 'data-ops-guild', 'Data Ops Guild', 'Messy in, trustworthy out. Extraction, cleaning, verification and a validation pass, so the dataset you build a decision on is one you can defend.', 'DataFox extracts → CSV Cleaner normalizes → ResearchOtter verifies → QA Fox validates', 640, 4.94, 231, 1288, 'available', 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', '2026-03-13T18:00:00.000Z', '2026-04-02T18:00:00.000Z')
