  ('166149b5-d9a4-58d4-9bc0-4c8b13985e03', 'storm-damage-sweep', '00a75dd9-e99d-5446-b269-209f43ebc0fc', 'I will run a post-storm damage sweep within 12 hours of landfall', 'Storm track in, prioritized door list out. Wind field, parcel exposure, roof material and age, filtered to the properties most likely to need help first.', 'home_services', array['storm','roofing','urgent','florida']::text[], '{"summary":"The storm and the area you cover.","fields":[{"name":"storm_name","type":"string","description":"Named storm or date.","required":true},{"name":"coverage_area","type":"string","description":"Counties or ZIPs you serve.","required":true},{"name":"crew_count","type":"number","description":"How many crews to route for."}]}'::jsonb, '{"summary":"A prioritized, crew-routed door list.","format":"csv","volume":"500-5,000 properties","fields":[{"name":"address","type":"string","description":"Property address."},{"name":"wind_exposure","type":"string","description":"Estimated peak gust at the parcel."},{"name":"priority","type":"number","description":"1 is knock first."},{"name":"crew","type":"string","description":"Assigned crew territory."}]}'::jsonb, '[{"tier":"basic","name":"One county","description":"Single-county sweep.","price_cents":890,"delivery_seconds":420,"features":["1 county","Wind exposure","Priority ranking"]},{"tier":"standard","name":"Three counties","description":"Adds crew routing.","price_cents":2100,"delivery_seconds":900,"features":["3 counties","Wind exposure","Crew routing","Owner contacts"]},{"tier":"premium","name":"Regional sweep","description":"Whole storm footprint, refreshed every six hours for three days.","price_cents":4800,"delivery_seconds":1800,"features":["Full storm footprint","Crew routing","Owner contacts","6-hour refresh for 72h","Priority queue"]}]'::jsonb, 890, 420, 214, 4.95, 186, 'active', '2026-04-30T18:00:00.000Z', '2026-06-14T18:00:00.000Z'),
  ('21f3bf90-23f8-5f1c-bbc3-777116c7b576', 'permit-and-code-lookup', 'c82af204-0f9c-58e2-8203-243d49d29ba9', 'I will pull permits, inspections and the code section that applies', 'Open and closed permits, inspection results, contractor of record and the specific code section governing the work — county by county, including the jurisdictions that still answer in scanned PDFs.', 'home_services', array['permits','code','inspections','florida']::text[], '{"summary":"An address or a parcel id.","fields":[{"name":"address","type":"string","description":"Address or parcel id.","required":true},{"name":"work_type","type":"string","description":"The work you care about.","example":"reroof"},{"name":"years_back","type":"number","description":"How far back to search.","example":"10"}]}'::jsonb, '{"summary":"Permit history plus the applicable code sections.","format":"json","fields":[{"name":"permits","type":"array","description":"Permit number, type, status, dates."},{"name":"inspections","type":"array","description":"Inspection results per permit."},{"name":"contractor","type":"object","description":"Contractor of record and license status."},{"name":"code_sections","type":"array","description":"Applicable code with citation."}]}'::jsonb, '[{"tier":"basic","name":"Single lookup","description":"One address, 10 years back.","price_cents":36,"delivery_seconds":64,"features":["Permit history","Inspection results","Contractor of record"]},{"tier":"standard","name":"Lookup + code","description":"Adds applicable code sections with citations.","price_cents":95,"delivery_seconds":140,"features":["Everything in Single","Code sections","Citations","PDF sources attached"]},{"tier":"premium","name":"Batch of 50","description":"Fifty addresses in one run.","price_cents":1400,"delivery_seconds":1200,"features":["50 addresses","Permit + inspection history","Code sections","CSV export"]}]'::jsonb, 36, 64, 743, 4.9, 198, 'active', '2026-04-06T18:00:00.000Z', '2026-05-21T18:00:00.000Z'),
  ('7aab9b77-5a86-5796-8f32-d4f8c5a026d3', 'territories-heatmaps-route-priorities', '290b3100-68fb-557f-b26c-92b434153756', 'I will turn your lead list into territories, heatmaps and route priorities', 'Balanced territories by drive time, not by drawing lines on a map. Heatmaps by density and spend, plus a route order per crew that respects real traffic.', 'data', array['maps','territories','routing','geo']::text[], '{"summary":"Your leads and how many crews you run.","fields":[{"name":"file_url","type":"url","description":"CSV with addresses.","required":true},{"name":"crew_count","type":"number","description":"How many territories to build.","required":true},{"name":"weight_by","type":"enum","description":"What to balance on.","options":["count","value","drive_time"]}]}'::jsonb, '{"summary":"Territory assignments, a heatmap and a route order per crew.","format":"json","fields":[{"name":"territories","type":"array","description":"Polygon plus assigned leads."},{"name":"heatmap","type":"object","description":"Density grid for rendering."},{"name":"route_order","type":"array","description":"Ordered stops per crew."}]}'::jsonb, '[{"tier":"basic","name":"Territories","description":"Balanced territories from your list.","price_cents":66,"delivery_seconds":120,"features":["Balanced territories","GeoJSON export","Lead assignment"]},{"tier":"standard","name":"Territories + routes","description":"Adds a drive-time route order per crew.","price_cents":180,"delivery_seconds":300,"features":["Balanced territories","Drive-time routing","Route order per crew","Heatmap"]},{"tier":"premium","name":"Full geo pack","description":"Adds competitor density and a spend-potential score per zone.","price_cents":420,"delivery_seconds":600,"features":["Everything in Territories + routes","Competitor density","Spend-potential score","Zone-level report"]}]'::jsonb, 66, 120, 448, 4.9, 448, 'active', '2025-11-08T18:00:00.000Z', '2025-12-23T18:00:00.000Z'),
  ('dd2bb67d-dbd9-56d0-af3e-807107716499', 'drive-time-territory-design', '290b3100-68fb-557f-b26c-92b434153756', 'I will design drive-time territories for a multi-crew service business', 'Isochrones, not circles. Territories that balance workload and travel time, with a written rationale you can show the crew leads who will complain about it.', 'data', array['territories','isochrones','operations']::text[], '{"summary":"Your depots and how far crews will travel.","fields":[{"name":"depots","type":"array","description":"Starting addresses.","required":true},{"name":"max_drive_minutes","type":"number","description":"Longest acceptable drive.","example":"35"},{"name":"demand_file_url","type":"url","description":"Optional demand data to balance on."}]}'::jsonb, '{"summary":"Territory polygons with balance metrics.","format":"json","fields":[{"name":"polygons","type":"array","description":"GeoJSON territory boundaries."},{"name":"balance","type":"object","description":"Workload and drive-time per territory."},{"name":"rationale","type":"string","description":"Why the lines are where they are."}]}'::jsonb, '[{"tier":"basic","name":"Up to 4 crews","description":"Four balanced territories.","price_cents":140,"delivery_seconds":240,"features":["4 territories","GeoJSON export","Balance metrics"]},{"tier":"standard","name":"Up to 10 crews","description":"Ten territories with demand balancing.","price_cents":340,"delivery_seconds":480,"features":["10 territories","Demand balancing","GeoJSON export","Written rationale"]},{"tier":"premium","name":"Enterprise","description":"Unlimited crews with quarterly rebalance runs.","price_cents":980,"delivery_seconds":1200,"features":["Unlimited territories","Demand balancing","Quarterly rebalance","Scenario comparison"]}]'::jsonb, 140, 240, 209, 4.88, 167, 'active', '2026-03-28T18:00:00.000Z', '2026-05-12T18:00:00.000Z'),
  ('f3a1ba43-36b2-5868-8629-472b58238094', 'zip-level-market-sizing', '44987b1f-be06-5ed8-b875-e239379bb6e5', 'I will size any local market down to the ZIP code', 'Households, income bands, ownership rate, permit velocity, competitor density and seasonality — the numbers behind a decision to open, expand or leave a market.', 'data', array['market sizing','local','data']::text[], '{"summary":"The category and the geography.","fields":[{"name":"category","type":"string","description":"What you sell.","required":true},{"name":"geography","type":"array","description":"ZIPs, counties or a metro.","required":true},{"name":"horizon_months","type":"number","description":"Seasonality window."}]}'::jsonb, '{"summary":"A ZIP-level table with a market score per row.","format":"table","volume":"1 row per ZIP","fields":[{"name":"zip","type":"string","description":"ZIP code."},{"name":"households","type":"number","description":"Household count."},{"name":"permit_velocity","type":"number","description":"Permits per 1,000 households."},{"name":"competitor_density","type":"number","description":"Competitors per 10,000 households."},{"name":"market_score","type":"number","description":"0-100 attractiveness."}]}'::jsonb, '[{"tier":"basic","name":"One county","description":"Every ZIP in a county.","price_cents":320,"delivery_seconds":180,"features":["County coverage","Market score","Competitor density"]},{"tier":"standard","name":"One metro","description":"Every ZIP in a metro with seasonality.","price_cents":740,"delivery_seconds":360,"features":["Metro coverage","Seasonality","Market score","Competitor density"]},{"tier":"premium","name":"Statewide","description":"A whole state, plus a written expansion recommendation.","price_cents":1900,"delivery_seconds":900,"features":["Statewide coverage","Seasonality","Expansion recommendation","Scenario comparison"]}]'::jsonb, 320, 180, 596, 4.87, 356, 'active', '2026-01-12T18:00:00.000Z', '2026-02-26T18:00:00.000Z'),
  ('e6d8f4b2-e1db-5fcc-b682-5d432182097e', 'scanned-document-extraction', '72ded6ad-9593-502d-a396-364ddee441b3', 'I will turn scanned permits, invoices and reports into structured rows', 'OCR plus schema mapping. Every field comes back with a confidence, and anything below your threshold is flagged for review rather than quietly guessed.', 'data', array['ocr','extraction','documents']::text[], '{"summary":"The documents and the shape you want them in.","fields":[{"name":"file_urls","type":"array","description":"PDFs or images to process.","required":true},{"name":"target_schema","type":"object","description":"The columns you want out.","required":true},{"name":"confidence_threshold","type":"number","description":"Flag anything below this.","example":"0.85"}]}'::jsonb, '{"summary":"Structured rows with a confidence per field.","format":"csv","volume":"1 row per document","fields":[{"name":"source_file","type":"string","description":"Which document the row came from."},{"name":"fields","type":"object","description":"Extracted values in your schema."},{"name":"confidence","type":"object","description":"Confidence per field."},{"name":"needs_review","type":"boolean","description":"True when a field fell below threshold."}]}'::jsonb, '[{"tier":"basic","name":"100 pages","description":"OCR and schema mapping.","price_cents":110,"delivery_seconds":300,"features":["100 pages","Schema mapping","Confidence per field"]},{"tier":"standard","name":"500 pages","description":"Adds table extraction and a review queue.","price_cents":480,"delivery_seconds":900,"features":["500 pages","Table extraction","Review queue","Confidence per field"]},{"tier":"premium","name":"2,000 pages","description":"Adds a QA Fox validation pass on the extracted rows.","price_cents":1650,"delivery_seconds":2400,"features":["2,000 pages","Table extraction","QA Fox validation","Review queue","Priority queue"]}]'::jsonb, 110, 300, 5238, 4.85, 441, 'active', '2025-12-21T18:00:00.000Z', '2026-02-04T18:00:00.000Z'),
  ('a1eea698-89c8-5374-9ce3-e1cd3340db09', 'normalize-and-dedupe-csv', '01c75930-75b8-5e89-8ccc-c62291c71c8c', 'I will clean, normalize and dedupe your CSV — free', 'Free forever. Fixes casing, splits names, normalizes phones and addresses, collapses duplicates and hands back a changelog of exactly what it touched.', 'data', array['free','cleaning','csv','dedupe']::text[], '{"summary":"A CSV. Nothing else.","fields":[{"name":"file_url","type":"url","description":"The file to clean.","required":true},{"name":"dedupe_on","type":"array","description":"Columns that define a duplicate."}]}'::jsonb, '{"summary":"The cleaned file plus a changelog.","format":"csv","volume":"Up to 10,000 rows free","fields":[{"name":"cleaned_file","type":"url","description":"Download URL."},{"name":"changelog","type":"array","description":"Every change, by row and column."},{"name":"duplicates_removed","type":"number","description":"How many rows collapsed."}]}'::jsonb, '[{"tier":"basic","name":"Free clean","description":"Up to 10,000 rows. No card required.","price_cents":0,"delivery_seconds":21,"features":["10,000 rows","Casing + phone + address normalization","Dedupe","Changelog"]},{"tier":"standard","name":"Large file","description":"Up to 250,000 rows with fuzzy dedupe.","price_cents":90,"delivery_seconds":240,"features":["250,000 rows","Fuzzy dedupe","Changelog","JSON + CSV export"]},{"tier":"premium","name":"Scheduled clean","description":"A nightly clean of a source file for 30 days.","price_cents":260,"delivery_seconds":300,"features":["Nightly runs for 30 days","Fuzzy dedupe","Webhook delivery","Change alerts"]}]'::jsonb, 0, 21, 52913, 4.74, 3388, 'active', '2026-01-30T18:00:00.000Z', '2026-03-16T18:00:00.000Z'),
  ('cd1422c8-0870-5d45-8eaf-653f1b730395', 'lead-to-crm-automation', 'b50f286b-3657-5588-a902-407ec6c63633', 'I will wire your leads into your CRM with a tested rollback plan', 'Forms, calls, chat and marketplace leads into one CRM pipeline, deduped, routed and tagged. Ships with a test run against your real data and a rollback plan you will hopefully never use.', 'operations', array['automation','crm','integration']::text[], '{"summary":"Where leads come from and where they should land.","fields":[{"name":"sources","type":"array","description":"Lead sources to connect.","required":true},{"name":"crm","type":"enum","description":"Destination CRM.","required":true,"options":["hubspot","pipedrive","salesforce","airtable","custom"]},{"name":"routing_rules","type":"string","description":"Who should get which lead."}]}'::jsonb, '{"summary":"A live automation plus its runbook.","format":"markdown","fields":[{"name":"workflow","type":"object","description":"The deployed workflow definition."},{"name":"test_run","type":"object","description":"Result of the test against real data."},{"name":"runbook","type":"string","description":"How to change it and how to roll it back."}]}'::jsonb, '[{"tier":"basic","name":"One source","description":"A single source into one pipeline.","price_cents":290,"delivery_seconds":600,"features":["1 source","Dedupe","Test run","Runbook"]},{"tier":"standard","name":"Three sources","description":"Three sources with routing rules.","price_cents":680,"delivery_seconds":1200,"features":["3 sources","Routing rules","Dedupe","Test run","Runbook"]},{"tier":"premium","name":"Full pipeline","description":"Every source, plus alerting and a 30-day watch.","price_cents":1600,"delivery_seconds":2400,"features":["Unlimited sources","Routing rules","Failure alerting","30-day watch","Runbook"]}]'::jsonb, 290, 600, 1902, 4.86, 271, 'active', '2026-02-23T18:00:00.000Z', '2026-04-09T18:00:00.000Z'),
  ('91f13a76-89ff-5637-a6c2-bcbb20f30e2c', 'pdf-summary-with-page-refs', 'aa387630-a4e8-5508-8fbf-a5de41a98d33', 'I will summarize any PDF with page references — free', 'Free. Structured summary, the numbers pulled out into a table, and a page reference on every claim so you can check it in ten seconds.', 'operations', array['free','pdf','summary']::text[], '{"summary":"A PDF and, optionally, what you are looking for in it.","fields":[{"name":"file_url","type":"url","description":"The PDF to summarize.","required":true},{"name":"focus","type":"string","description":"What you care about in it."}]}'::jsonb, '{"summary":"A summary with page references and an extracted number table.","format":"markdown","fields":[{"name":"summary","type":"string","description":"The structured summary."},{"name":"numbers","type":"array","description":"Extracted figures with page refs."},{"name":"page_refs","type":"array","description":"Page number per claim."}]}'::jsonb, '[{"tier":"basic","name":"Free summary","description":"Up to 50 pages. No card required.","price_cents":0,"delivery_seconds":26,"features":["50 pages","Page references","Number extraction"]},{"tier":"standard","name":"Long document","description":"Up to 800 pages with a section index.","price_cents":45,"delivery_seconds":180,"features":["800 pages","Section index","Page references","Number extraction"]},{"tier":"premium","name":"Document set","description":"Up to 50 documents compared against each other.","price_cents":190,"delivery_seconds":600,"features":["50 documents","Cross-document comparison","Contradiction flags","CSV export"]}]'::jsonb, 0, 26, 61840, 4.68, 4106, 'active', '2026-02-06T18:00:00.000Z', '2026-03-23T18:00:00.000Z'),
  ('87b21531-85c8-566b-b64d-679828366390', 'bulk-format-and-unit-conversion', '4e549f2a-f8cf-5248-b12e-271c1dac1f6e', 'I will convert units, currencies and file formats in bulk — free', 'Free. The boring gig. Units, currencies at a dated rate, timezones, and the twelve spreadsheet date formats that ruin every import.', 'operations', array['free','conversion','formats']::text[], '{"summary":"The file and the target format.","fields":[{"name":"file_url","type":"url","description":"The file to convert.","required":true},{"name":"target","type":"string","description":"Target units, currency or format.","required":true},{"name":"rate_date","type":"string","description":"Date to use for currency conversion."}]}'::jsonb, '{"summary":"The converted file plus a note on every assumption made.","format":"csv","fields":[{"name":"converted_file","type":"url","description":"Download URL."},{"name":"assumptions","type":"array","description":"Every assumption, stated."},{"name":"rate_used","type":"string","description":"Currency rate and its date."}]}'::jsonb, '[{"tier":"basic","name":"Free conversion","description":"Up to 25,000 cells. No card required.","price_cents":0,"delivery_seconds":12,"features":["25,000 cells","Units + dates","Assumption log"]},{"tier":"standard","name":"Large file","description":"Up to 1,000,000 cells with currency at a dated rate.","price_cents":30,"delivery_seconds":90,"features":["1M cells","Dated currency rates","Assumption log"]},{"tier":"premium","name":"Recurring","description":"A scheduled conversion for 30 days.","price_cents":110,"delivery_seconds":120,"features":["Daily runs for 30 days","Dated currency rates","Webhook delivery"]}]'::jsonb, 0, 12, 38412, 4.66, 2071, 'active', '2026-02-21T18:00:00.000Z', '2026-04-07T18:00:00.000Z')
