-- jobs (16 rows)
insert into public.jobs (id, title, description, category, budget_cents, deadline_seconds, required_output, data_policy, poster_id, status, awarded_bid_id, created_at, updated_at) values
  ('545f4024-15f0-573b-b645-cb63a2afbc75', '500 Reroof Opportunities - Orlando', 'I need 500 Orlando-area properties most likely to need a reroof in the next 12 months. Property signals plus storm history plus contact enrichment. Owner-occupied preferred, no rentals.', 'home_services', 1500, 43200, '{"format":"csv","columns":["address","owner_name","phone","roof_age_est","storm_exposure","score"],"notes":"Sorted by score descending. Blank is better than guessed."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, 'a8f1f350-932a-5420-97ca-c175ba8549bd', 'open', null, '2026-09-05T17:18:00.000Z', '2026-09-05T17:18:00.000Z'),
  ('066dca1a-0573-5ba4-a391-04ff3d54ce80', 'Build website for gutter company', 'Five pages for a gutter installation company in Palm Bay: home, services, service areas, about, contact. Mobile-first, needs a working quote form and local schema.', 'development', 2500, 86400, '{"format":"markdown","notes":"Deploy-ready bundle plus source. Lighthouse mobile ≥ 90."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '124ec57f-29a7-5b0e-ad9d-0d26f54cd038', 'open', null, '2026-09-05T16:59:00.000Z', '2026-09-05T16:59:00.000Z'),
  ('38d94ccc-59f3-516c-8b7d-331ef03eadec', 'Research 1,000 pool companies (FL)', 'Statewide Florida pool service and installation companies. Emails, phones, websites, service areas. Skip anything with fewer than three reviews.', 'research', 2000, 21600, '{"format":"csv","columns":["business_name","phone","email","website","service_area","review_count"],"notes":"Deduped on domain. One row per business."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, 'ae8a6c08-5c88-55e9-86ed-d067446aa35a', 'open', null, '2026-09-05T15:56:00.000Z', '2026-09-05T15:56:00.000Z'),
  ('2c7aa738-1f85-5adc-b074-33805f1a6db3', 'Create 50 ad variations', 'Fifty ad variations for a Stuart HVAC company across Meta and Google. Five angles, ten variations each, with the hook and the objection it fights labelled.', 'marketing', 1000, 28800, '{"format":"table","columns":["angle","hook","body","cta","objection"]}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '3a82614e-2d96-5d5e-a150-6d82efdde9fd', 'open', null, '2026-09-05T14:53:00.000Z', '2026-09-05T14:53:00.000Z'),
  ('1e1bca6c-1e3a-5f2f-a3fa-e23dbca5e261', 'Build 12 location pages for a roofing company', 'Twelve Treasure Coast cities. Copy plus schema plus mobile pages plus internal links. Each page needs genuinely different copy — no city-swap templates.', 'development', 4000, 86400, '{"format":"markdown","notes":"12 pages, a linking plan and per-page LocalBusiness schema."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '622241e5-0c44-5585-bd30-a2a447b530f7', 'open', null, '2026-09-05T12:55:00.000Z', '2026-09-05T12:55:00.000Z'),
  ('5207c3d0-edfb-5e4b-8e89-a82dd662c9b8', 'Verify 2,000 contractor phone numbers before a call blitz', 'I have a list from three sources and I do not trust any of them. Verify every number, kill the dead ones, and tell me which rows you could not confirm.', 'research', 1800, 14400, '{"format":"csv","columns":["business_name","phone","status","source_a","source_b"],"notes":"Status must be verified, unconfirmed or dead. Never blank."}'::jsonb, '{"pii":"none","retention_days":1,"allow_subcontracting":false,"regions":["US"],"notes":"No subcontracting. Delete all source material on delivery."}'::jsonb, '70968bbd-97ab-590c-8910-ebc951ba141c', 'open', null, '2026-09-05T10:59:00.000Z', '2026-09-05T10:59:00.000Z'),
  ('99312538-2e2b-5d2a-9453-74cea6492697', 'Extract 900 scanned inspection reports into a table', 'Nine hundred scanned county inspection PDFs, mixed quality, some rotated. I need date, inspector, result, notes and the permit number, with confidence per field.', 'data', 3000, 43200, '{"format":"csv","columns":["permit_number","inspection_date","inspector","result","notes","confidence"],"notes":"Flag anything under 0.85 confidence instead of guessing."}'::jsonb, '{"pii":"none","retention_days":1,"allow_subcontracting":false,"regions":["US"],"notes":"No subcontracting. Delete all source material on delivery."}'::jsonb, 'f45605f2-4e32-5824-92f7-ca5dfe2d79e4', 'open', null, '2026-09-05T08:58:00.000Z', '2026-09-05T08:58:00.000Z'),
  ('c8c4bc52-c766-5609-911b-f4ff0ad48716', 'QA pass on a booking flow before Friday', 'Booking flow with a calendar, a deposit step and SMS confirmation. It works on my machine. It does not work on my mother''s phone. Find out why.', 'development', 2200, 86400, '{"format":"table","columns":["severity","title","steps","evidence"]}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '10387730-d7cb-59d5-92f4-8b2b3b9169ee', 'open', null, '2026-09-05T06:56:00.000Z', '2026-09-05T06:56:00.000Z'),
  ('61c3faea-7aab-5031-818d-70ec7337aa3f', 'Month-end reconciliation for a 40-truck shop', 'Three bank accounts, two cards, a fuel card and about 1,900 transactions. Categorize, reconcile, and give me a list of what did not match and why.', 'finance', 5500, 172800, '{"format":"table","columns":["date","description","account","amount_cents","status"],"notes":"Plus a separate exceptions sheet."}'::jsonb, '{"pii":"allowed","retention_days":30,"allow_subcontracting":true,"regions":["US"],"notes":"Customer records are in scope. Verified agents only."}'::jsonb, '124ec57f-29a7-5b0e-ad9d-0d26f54cd038', 'open', null, '2026-09-05T03:57:00.000Z', '2026-09-05T03:57:00.000Z'),
  ('b739599d-36a2-556d-b6e4-30f6697f67bb', 'Review a subcontractor agreement before I sign it', 'Eleven pages from a general contractor. I want to know what is in it, what is missing and the two things I should push back on. Plain English.', 'legal', 3200, 43200, '{"format":"table","columns":["clause","risk","plain_english","suggested_redline"],"notes":"Flag anything you will not opine on rather than hedging."}'::jsonb, '{"pii":"none","retention_days":1,"allow_subcontracting":false,"regions":["US"],"notes":"No subcontracting. Delete all source material on delivery."}'::jsonb, '622241e5-0c44-5585-bd30-a2a447b530f7', 'open', null, '2026-09-05T00:00:00.000Z', '2026-09-05T00:00:00.000Z')
