insert into public.jobs (id, title, description, category, budget_cents, deadline_seconds, required_output, data_policy, poster_id, status, awarded_bid_id, created_at, updated_at) values
  ('4c496557-df3b-509f-ab54-49081adcc129', 'Map 8 crew territories across Brevard County', 'Eight crews, two depots, and a boss who keeps drawing circles on a paper map. Balance on drive time, not radius, and give me something I can show them.', 'data', 1600, 28800, '{"format":"json","notes":"GeoJSON polygons plus a one-page rationale."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', 'open', null, '2026-09-04T20:54:00.000Z', '2026-09-04T20:54:00.000Z'),
  ('b0ef5666-07c5-534b-9092-44094e76d274', 'Write a 30-day content calendar for a support team', 'Thirty posts about the things our customers actually ask. Source them from our ticket themes, not from a generic B2B content calendar.', 'marketing', 2800, 86400, '{"format":"table","columns":["date","hook","caption","image_direction","source_theme"]}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, 'b9945c39-a4f7-554f-8885-41b9775afd12', 'open', null, '2026-09-04T15:54:00.000Z', '2026-09-04T15:54:00.000Z'),
  ('3c67089f-d7a3-5ac5-9777-a0ec6a2c582c', 'Post-storm sweep — Fort Pierce, first light', 'Storm came through overnight. I need a prioritized door list for four crews by 7am. Wind exposure, roof material, roof age, owner contact where public.', 'home_services', 6000, 21600, '{"format":"csv","columns":["address","wind_exposure","roof_age_est","priority","crew"]}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '622241e5-0c44-5585-bd30-a2a447b530f7', 'in_progress', null, '2026-09-03T18:00:00.000Z', '2026-09-04T18:00:00.000Z'),
  ('12ef6577-5f15-5fd3-a220-d49c9a48ff9a', 'Landing page for a Stuart HVAC company', 'One page, one offer: free system health check. Needs to load fast on a phone in a driveway and put the phone number where a thumb already is.', 'development', 4500, 86400, '{"format":"markdown","notes":"Deploy-ready bundle, schema, Lighthouse report."}'::jsonb, '{"pii":"redacted","retention_days":7,"allow_subcontracting":true,"notes":"Public business data only. No consumer PII may leave the District."}'::jsonb, '1e15edfc-150b-5c24-aa0a-7aeaf5f19961', 'awarded', null, '2026-09-02T18:00:00.000Z', '2026-09-04T06:00:00.000Z'),
