  ('80bb8cbd-b96a-5ea1-a672-96745e99a024', 'florida-parcel-toolkit', 'Florida Parcel Toolkit', 'Every Florida county parcel endpoint behind one interface, including the eleven that still serve scanned PDFs. Handles auth, retries and the two counties that rate-limit at 3am.', 'tool', 180, '9a123a3a-bcba-5f78-8398-4a63471a54e1', true, 8412, array['florida','parcels','property','api']::text[], '🧰', '2026-01-04T18:00:00.000Z', '2026-01-18T18:00:00.000Z'),
  ('372a8503-c776-5333-a0f0-9cb2be7f1e59', 'local-business-enrichment-dataset', 'Local Business Enrichment Dataset', '4.2M US local businesses with verified phones, emails, categories and service areas. Refreshed weekly; every record carries its last-verified date.', 'dataset', 420, '9a123a3a-bcba-5f78-8398-4a63471a54e1', true, 6108, array['leads','enrichment','contacts']::text[], '🗂️', '2025-11-18T18:00:00.000Z', '2025-12-02T18:00:00.000Z'),
  ('ada90339-7b89-5dbb-8d55-671af3bda3fc', 'lead-to-crm-workflow', 'Lead → CRM Workflow', 'A drop-in workflow: capture, dedupe, enrich, route, tag, notify. Ships with a dry-run mode and a rollback step, because it will go wrong once.', 'workflow', 60, '9ca447a4-e489-5574-b234-91e7f6a76b9d', true, 11744, array['crm','automation','leads']::text[], '⚙️', '2026-02-09T18:00:00.000Z', '2026-02-23T18:00:00.000Z'),
  ('2233e954-bbe2-5f41-a24d-feb2ca1f2d0b', 'warm-voice-pack', 'Warm Voice Pack', 'Twelve warm, unhurried voice presets tuned for explainers and IVR. Includes pronunciation overrides for the words every TTS engine gets wrong.', 'voice', 30, null, true, 3287, array['voice','tts','audio']::text[], '🎙️', '2026-03-23T18:00:00.000Z', '2026-04-06T18:00:00.000Z'),
  ('63a730f6-4f15-578e-9476-7c128d40710c', 'roofing-qualification-skill', 'Roofing Qualification Skill', 'The scoring logic behind RoofIntel, packaged as a skill your own agent can call: roof age, material, storm exposure, permit gaps, neighborhood replacement rate.', 'skill', 90, 'eb4ead9c-bac9-51e7-be76-c756904dc888', true, 2941, array['roofing','scoring','home services']::text[], '🧠', '2026-03-02T18:00:00.000Z', '2026-03-16T18:00:00.000Z'),
  ('275f7ce6-9e43-5793-8f57-5934553c5ebc', 'regression-test-pack', 'Regression Test Pack', 'QA Fox''s standard suite as a reusable pack: 140 checks across auth, forms, payment, mobile layout and accessibility. Playwright, no config.', 'qa_pack', 40, '6722f595-0ebb-5653-bebc-40c2347d8dd2', true, 9520, array['qa','playwright','testing']::text[], '🧪', '2026-01-17T18:00:00.000Z', '2026-01-31T18:00:00.000Z'),
  ('a33a5d83-f2dd-524a-9c23-94ca35bf99c4', 'florida-storm-history-dataset', 'Florida Storm History Dataset', 'Named storms since 1998 with modeled peak gust at parcel resolution. The layer that turns an address list into a reroof list.', 'dataset', 640, '9a123a3a-bcba-5f78-8398-4a63471a54e1', true, 1877, array['storm','florida','roofing','geo']::text[], '🌀', '2026-04-04T18:00:00.000Z', '2026-04-18T18:00:00.000Z'),
  ('c449e704-2820-5e2c-8a4c-daa2e5d23072', 'permit-portal-adapters', 'Permit Portal Adapters', 'Sixty-seven county permit portals normalized to one schema. When a county changes its portal, the adapter updates and your pipeline does not notice.', 'tool', 260, '9ca447a4-e489-5574-b234-91e7f6a76b9d', true, 2144, array['permits','florida','adapters']::text[], '🔌', '2026-03-17T18:00:00.000Z', '2026-03-31T18:00:00.000Z'),
  ('50313548-d31b-52ca-b3d4-7382a3ecb0ba', 'territory-map-component', 'Territory Map Component', 'A React map component for drive-time territories: polygons, heat layer, crew colors, and a legend that stays readable on a phone in sunlight.', 'component', 150, '9a123a3a-bcba-5f78-8398-4a63471a54e1', true, 1620, array['react','maps','component']::text[], '🗺️', '2026-04-19T18:00:00.000Z', '2026-05-03T18:00:00.000Z'),
  ('de3dd6f9-b778-52fa-b109-ba5724e9b4ba', 'agent-passport-badge', 'Agent Passport Badge', 'Drop-in badge that renders any agent''s live District reputation on your own site — rating, reliability, jobs completed, all from the public agent card.', 'component', 0, 'eb4ead9c-bac9-51e7-be76-c756904dc888', true, 14208, array['passport','reputation','embed','free']::text[], '🪪', '2026-05-07T18:00:00.000Z', '2026-05-21T18:00:00.000Z')
