insert into public.market_items (id, slug, title, description, kind, price_cents, seller_store_id, verified, downloads, tags, icon_emoji, created_at, updated_at) values
  ('6e98ae5a-1cf9-5838-b749-2d2d0c74dee1', 'contract-clause-library', 'Contract Clause Library', '480 clauses with plain-English explanations and a suggested redline for each. The knowledge base behind ClauseCat, licensed for your own agent.', 'skill', 480, '6722f595-0ebb-5653-bebc-40c2347d8dd2', true, 812, array['legal','contracts','clauses']::text[], '⚖️', '2026-04-10T18:00:00.000Z', '2026-04-24T18:00:00.000Z'),
  ('37b00abc-f13c-5cf7-b424-464d642fec17', 'support-macro-library', 'Support Macro Library', 'Nine hundred support macros clustered by intent, tone-matched to three brand voices. Import into any helpdesk in about four minutes.', 'skill', 120, null, true, 4033, array['support','macros','helpdesk']::text[], '🎧', '2026-04-25T18:00:00.000Z', '2026-05-09T18:00:00.000Z'),
  ('d38f397d-5285-52ab-ae65-50c996cf4855', 'florida-contractor-license-dataset', 'Florida Contractor License Dataset', 'Every active Florida contractor license with status, class, insurance expiry and disciplinary history. Updated nightly from the state register.', 'dataset', 340, '9ca447a4-e489-5574-b234-91e7f6a76b9d', true, 2588, array['florida','licenses','contractors']::text[], '📋', '2026-03-30T18:00:00.000Z', '2026-04-13T18:00:00.000Z'),
  ('4cd0faf8-6f16-5918-955e-80f1b52345c7', 'onboarding-email-workflow', 'Onboarding Email Workflow', 'A seven-email onboarding sequence with branching on activation events, written by CopyCat and wired by FlowForge. Bring your own ESP.', 'workflow', 95, '90260f07-1c69-596b-9abb-74a04ef6dd74', true, 3711, array['email','onboarding','lifecycle']::text[], '✉️', '2026-05-01T18:00:00.000Z', '2026-05-15T18:00:00.000Z'),
  ('73886017-fd7b-54c7-a04e-0edfab046afc', 'accessibility-audit-pack', 'Accessibility Audit Pack', 'WCAG 2.2 AA checks with real screen-reader traversal, not just an axe scan. Returns failures grouped by the fix, so one change closes nine issues.', 'qa_pack', 180, '6722f595-0ebb-5653-bebc-40c2347d8dd2', true, 2266, array['accessibility','wcag','qa']::text[], '♿', '2026-05-14T18:00:00.000Z', '2026-05-28T18:00:00.000Z'),
  ('757f4399-59c8-57f2-ba58-43f60d44348a', 'bright-voice-pack', 'Bright Voice Pack', 'Eight energetic presets for short-form and ads, with a loudness profile that survives platform normalization.', 'voice', 35, null, false, 941, array['voice','tts','shortform']::text[], '🔊', '2026-06-01T18:00:00.000Z', '2026-06-15T18:00:00.000Z')
