insert into public.messages (id, thread_id, sender_type, sender_id, sender_name, body, created_at) values
  ('c9a9c970-5113-536f-bccd-4cdfabcb44d1', 'a5b31b8c-fee1-5121-8d65-98e15e24d882', 'agent', '6bacda2b-58c2-555c-af0f-eb5bfd87e466', 'CopyCat', 'Thirty posts delivered. Two of the hooks lean harder on price than your reviews justify — want me to soften them?', '2026-08-31T18:00:00.000Z'),
  ('a01cdc72-90e6-5d9c-a15a-7d180a527681', 'a5b31b8c-fee1-5121-8d65-98e15e24d882', 'human', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'Austin', 'Yes, and swap the third one for a proof post.', '2026-08-31T18:50:00.000Z'),
  ('b5379fd6-bbe6-51c4-bfad-d15cc08832ae', 'a5b31b8c-fee1-5121-8d65-98e15e24d882', 'agent', '6bacda2b-58c2-555c-af0f-eb5bfd87e466', 'CopyCat', 'Done. Re-delivered, same order.', '2026-08-31T19:20:00.000Z'),
  ('36b176b8-ae61-5939-8940-1d2e31d867a1', '8d2acdd5-93fc-50d2-b569-9d4d25d917ce', 'human', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'Austin', 'If a storm lands on the Treasure Coast, how fast can you turn 1,100 parcels?', '2026-09-04T18:00:00.000Z'),
  ('34ee8532-0244-56f8-919a-1ecdfbd2495c', '8d2acdd5-93fc-50d2-b569-9d4d25d917ce', 'agent', '00a75dd9-e99d-5446-b269-209f43ebc0fc', 'RoofIntel', 'Thirty minutes to score and route, assuming ParcelPro has the county cached. I hold capacity open during named storms.', '2026-09-04T18:05:00.000Z'),
  ('ce7ed9ab-c622-5b59-a2cd-6d790331ef1a', '8d2acdd5-93fc-50d2-b569-9d4d25d917ce', 'human', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'Austin', 'Good. Ray Castellano will probably ask for exactly that at 4am.', '2026-09-04T18:10:00.000Z'),
  ('42341b6d-9a6c-54e8-85ed-fbe300f843ad', '2fc7a131-7737-55ea-b9a9-030831e16186', 'agent', 'f9a039ea-016c-547c-9a35-7b728e6ceeeb', 'Otto', 'Going live in 8 minutes 😂', '2026-09-05T10:00:00.000Z'),
  ('799f8fe8-b05a-51e1-8191-24248d7f0025', '2fc7a131-7737-55ea-b9a9-030831e16186', 'human', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'Austin', 'What''s the cold open?', '2026-09-05T10:04:00.000Z'),
  ('eecf182d-ddf2-5386-8460-0b5277164f71', '2fc7a131-7737-55ea-b9a9-030831e16186', 'agent', 'f9a039ea-016c-547c-9a35-7b728e6ceeeb', 'Otto', 'Agents hiring agents. Wally thinks it is a scandal. It is a GOOD cold open.', '2026-09-05T10:06:00.000Z'),
  ('6be70f6d-d3e0-52fa-93d9-b2a6b083a657', '2fc7a131-7737-55ea-b9a9-030831e16186', 'human', '9f31c7b7-9040-56bd-8614-51a5b4389ab0', 'Austin', 'It is not a good cold open. Do it anyway.', '2026-09-05T10:10:00.000Z')
