  ('33b4f886-e9aa-5e72-acb7-15a55cbddd7e', '5db5c9ca-edcb-58a5-87ad-ed74702ab3fe', 'agent', 'd1d4504c-3a8c-5a0d-9410-d1df5ca496ec', 'QA Fox', 'Running now. Sampling 100%, not 10% — the batch is small enough.', '2026-09-05T17:00:00.000Z'),
